create table RB_TDA_HIST (SEQ_NO VARCHAR(50) not null  ,INTERNAL_KEY INT not null  ,CLIENT_NO VARCHAR(22) not null  ,ACCT_OPEN_DATE TIMESTAMP(3) null  ,MATURITY_DATE TIMESTAMP(3) null  ,ACCT_MOVT_DATE TIMESTAMP(3) not null  ,MOVT_STATUS VARCHAR(1) null  ,ADD_TERM INT null  ,TERM VARCHAR(5) null  ,TERM_TYPE VARCHAR(1) null  ,AUTO_RENEW_ROLLOVER VARCHAR(1) null  ,PARTIAL_RENEW_ROLL VARCHAR(1) null  ,PARTIAL_RENEW_AMT DECIMAL(17,2) null  ,ADDTL_PRINCIPAL VARCHAR(1) null  ,ROLLOVER_NO INT null  ,RENEW_NO INT null  ,TDA_STATUS VARCHAR(1) null  ,RENEW_TIMES INT null  ,REV_SEQ_NO VARCHAR(50) null  ,TRAN_SEQ_NO VARCHAR(50) null  ,TDA_CERTIFICATE_NO VARCHAR(50) null  ,ACCT_LEVEL_INT_RATE DECIMAL(15,8) null  ,LOST_NO VARCHAR(50) null  ,REFERENCE VARCHAR(60) null  ,TAX_AMT DECIMAL(17,2) null  ,DEBT_AMT DECIMAL(17,2) null  ,PRINCIPAL_AMT DECIMAL(17,2) null  ,PRINCIPAL_AMT_ACTUAL DECIMAL(17,2) null  ,GROSS_INTEREST_AMT DECIMAL(17,2) null  ,INT_ADJ DECIMAL(17,2) null  ,INT_ADJ_CTD DECIMAL(17,2) null  ,NET_INTEREST_AMT DECIMAL(17,2) null  ,SPREAD_RATE DECIMAL(15,8) null  ,DEBT_INT_RATE DECIMAL(15,8) null  ,TRAN_SCENE VARCHAR(50) null  ,USER_ID VARCHAR(30) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  , primary key(SEQ_NO,INTERNAL_KEY,CLIENT_NO,ACCT_MOVT_DATE));